INSERT INTO `inspections` (`id`, `case_reference`, `entity_id`, `template_id`, `type_code`, `stage`, `permit_number`, `application_number`, `permit_issued_on`, `reviewed_on`, `permit_expiry`, `contractor`, `supervisor`, `building_status`, `dwelling_unit`, `has_physical_plan`, `building_category`, `on_main_corridor`, `corridor_road`, `inspection_date`, `visit_type`, `previous_inspection_id`, `visit_number`, `status`, `inspector_id`, `inspector_name`, `district_id`, `observations`, `recommendations`, `owner_recommendations`, `owner_rep_name`, `earned_score`, `possible_score`, `compliance`, `legacy_id`, `deleted_at`, `deleted_by`, `deleted_reason`, `created_at`, `updated_at`, `occupation_permit_number`, `occupation_permit_year`, `manager_name`, `manager_telephone`, `wastewater_system_type`, `wastewater_system_type_other`, `stp_type`, `stp_type_other`, `design_capacity_m3`, `population_served`, `water_consumption_m3`, `year_constructed`, `last_maintenance_date`, `last_desludging_date`, `desludging_frequency`, `operational_status`, `stp_general_condition`, `effluent_test_date`, `laboratory_name`, `final_discharge_point`, `septic_tank_type`, `septic_chamber_count`, `septic_tank_material`, `septic_tank_capacity`, `septic_year_installed`, `distance_to_foundation_m`, `septic_tank_location`, `absorption_field_condition`, `effluent_disposal_method`, `desludging_provider`, `tank_adequacy`, `septic_observations`, `non_compliances`, `non_compliances_other`, `key_findings`, `environmental_risks`, `wastewater_compliance_status`, `decision_taken`, `wastewater_fine_amount`, `wastewater_compliance_deadline`, `wastewater_followup_date`) VALUES
(22, NULL, 18, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 8, 'Thierry', 1, 'The petrol station was found non compliant', '1. Install a water-based firefighting system (50 m³ tank, 2-bar pump, hose reels, and fire hydrants).\r\n2. Provide additional fire extinguishers (2× 9 kg DCP, 2× 9 kg CO₂, and 2× 9 kg Foam).\r\n3. Install sufficient CCTV cameras with a central control room (storage capacity must be at least 3 months).\r\n4. Test the lightning protection system regularly every six months and maintain a record of test results.\r\n5. Install a fully functional fire alarm system (smoke detectors, manual call points, and control panel).\r\n6. Identify and clearly mark the assembly point, and display emergency phone numbers.\r\n7. Provide the retail license, Calibration Certificate, and occupation permit via email.\r\n8. Provide a sufficient number of fire extinguishers in all buildings located on the station plot.', NULL, NULL, 54.50, 99.00, 55.05, NULL, NULL, NULL, NULL, '2026-08-10 06:32:03', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(23, NULL, 19, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 8, 'NITINGENERA Thierry', 1, NULL, '1. To install full functional water based fire fighting system (30m³ tank, 8 bar pump, hydrant, and hose reel).\r\n2. To provide additional 20kg DCP and 9kg of CO₂ fire extinguishers.\r\n3. To do maintenance of fire alarm system.\r\n4. To increase storage capacity of CCTV cameras to 3 months.\r\n5. To provide at least 2 changing rooms.', NULL, NULL, 38.50, 99.00, 38.89, NULL, NULL, NULL, NULL, '2026-08-10 06:52:45', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(24, NULL, 20, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a.	To install one (1) additional 9 kg foam fire extinguisher and one (1) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb.	To repair and maintain water based firefighting system (fire hydrants and hose reel) to ensure they are fully operational.\r\nc.	To increase the water reserve tank capacity to a minimum of 30 m³.\r\nd.	To install Water pressure pump of at least 8 bar.\r\ne.	To maintain or replace fire alarm system control panel.\r\nf.	To display emergency evacuation plan.\r\ng.	To increase the storage capacity of CCTV cameras in order to retain footage for at least three (3) months.\r\nh.	To avail trained security staff from a registered security company.\r\ni.	To carry out maintenance of generator and ensure that it operates automatically.\r\nj.	To conduct lightning protection system testing every six (6) months and maintain proper test records for verification during inspections.\r\nk.	To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw', NULL, NULL, 50.50, 100.00, 50.50, NULL, NULL, NULL, NULL, '2026-08-10 07:00:33', '2026-08-10 08:40:43', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(25, NULL, 21, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, NULL, '1.Activate and ensure the fire alarm system and its control panel are fully operational.\r\n2.Install emergency evacuation plans, assembly point signs, and emergency contact number signs at appropriate locations.\r\n3.Increase the pressure of the water-based firefighting system to the required level (approximately 2 bar, as indicated).\r\n4.Obtain or renew valid electrical installation and lightning protection certificates from licensed service providers.\r\n5.Provide additional fire extinguishers where necessary and service/refill the existing expired extinguishers.', NULL, NULL, 71.00, 100.00, 71.00, NULL, NULL, NULL, NULL, '2026-08-10 07:00:59', '2026-08-10 07:44:07', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(26, NULL, 22, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'The station is partially compliant with the applicable requirements', '1. Test the lightning protection system every 6 months and obtain the test results report.\r\n\r\n\r\n\r\n2. Upgrade CCTV system to retain footage for at least 3 months. \r\n\r\n   Recommended: Install CCTV cameras with 3 months storage capacity._\r\n\r\n\r\n\r\n3. Increase fire pump capacity to at least 8 bar.\r\n\r\n\r\n\r\n4. Install assembly point signs.\r\n\r\n\r\n\r\n5. Remove waste materials stored around the generator room.\r\n\r\n\r\n\r\n6. Restock the First Aid kit  some items are missing.\r\n\r\n\r\n\r\n7. Provide changing rooms for both male and female staff and display signage.\r\n\r\n\r\n\r\n8. Repair damaged dustbins and increase the number of dustbins in the toilets.\r\n\r\n\r\n\r\n9. Maintain the paved compound near the parking area to keep it clean and in good condition.', NULL, NULL, 74.00, 100.00, 74.00, NULL, NULL, NULL, NULL, '2026-08-10 07:05:59', '2026-08-13 06:22:15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(27, NULL, 23, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install one (1) additional 9 kg foam fire extinguisher and one (1) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb. To repair and maintain water based firefighting system (fire hydrants and hose reel) to ensure they are fully operational.\r\nc. To replace existing water pump with another of at least of 8 bars.\r\nd. To increase the water reserve tank capacity to a minimum of 30 m³.\r\ne. To make an emergency assembly point accessible.\r\nf. To display emergency evacuation plan.\r\ng. To increase the storage capacity of CCTV cameras in order to retain footage for at least three (3) months.\r\nh. To install and clearly display warning notices and safety pictograms on canopy columns, vent pipes, and storage tank areas, ensuring they are visible from a minimum distance of 7.5 m. Entrance and exit signs should also be provided using illuminated or retro-reflective materials and be clearly readable from a minimum distance of 50 m.\r\ni. To replace the existing generator with an automatic standby generator.\r\nj. To conduct lightning protection system testing every six (6) months and maintain proper test records for verification during inspections.\r\nk. To provide at least two (2) changing rooms.\r\nl. To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw', NULL, NULL, 61.50, 100.00, 61.50, NULL, NULL, NULL, NULL, '2026-08-10 07:09:25', '2026-08-11 08:15:13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(28, NULL, 24, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 8, 'NITINGENERA Thierry', 1, NULL, 'To increase storage capacity of CCTV camera to 3 months.\r\n1. To provide additional one piece of 25kg DCP fire extinguisher.\r\n2. To install fully functional water-based firefighting system (30\\text{ m}^3 tank, 8 bar pump, hose reel, and fire hydrant).\r\n3. To install fully functional fire alarm system with control panel.\r\n4. Mark clearly entrance and exit.\r\n5. To test para-lightning system regularly to check if it\'s still effective.\r\n6. To make the back-up generator automatic in case of power outage.', NULL, NULL, 59.50, 99.00, 60.10, NULL, NULL, NULL, NULL, '2026-08-10 07:30:01', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(29, NULL, 25, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, NULL, '1. Traffic & Entrance Safety\r\n\r\nClear all road blocking items and install safety measures so drivers can see clearly.\r\n\r\nPut up bright, easy-to-read entrance and exit signs that can be read from at least 7.5 meters away.\r\n\r\n2. Fire Safety & Emergency Response\r\n\r\nFix the fire alarm panel, main system, and all connected accessories so they work properly.\r\n\r\nAdd two fire extinguishers: one 9kg foam and one 25kg powder extinguisher.\r\n\r\nPut emergency evacuation maps in clear places and post emergency phone numbers all around the compound.\r\n\r\n3. Water System Upgrade\r\n\r\nAdd a 20m³ water tank to the current tanks to reach a total of 30m³ of stored water.\r\n\r\nRepair the water pump and make sure it pumps water at 8 bar pressure or more.\r\n\r\n4. Security & Power\r\n\r\nInstall CCTV cameras across the whole compound with at least 3 months of saved video storage.\r\n\r\nInstall an automatic backup generator or power system to keep power on during outages.\r\n\r\n5. Required Certificates & Email Documents\r\n\r\nSend the following documents to inspection@gasabo.gov.rw:\r\n\r\nFuel tank calibration certificate\r\n\r\nPhotos/proof of dispensers and safety equipment\r\n\r\nValid Retail license\r\n\r\nValid Insurance policy\r\n\r\nGet a valid electrical installation certificate.\r\n\r\nFollow local zoning rules and get all required official permissions.', NULL, NULL, 59.00, 100.00, 59.00, NULL, NULL, NULL, NULL, '2026-08-10 07:38:33', '2026-08-11 10:40:11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(30, NULL, 26, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'the station is not complying with fire safety and security system', '1.Upgrade CCTV camera storage to retain footage for at least 3 months / 90 days.\r\n\r\n2. Increase fire pump pressure to a minimum of 8 bar.\r\n\r\n3. Repair and maintain the fire alarm system.\r\n\r\n4. Test the lightning protection system every 6 months by a professional engineer.\r\n\r\n5. Display illuminated entrance and exit signs and designate assembly points.\r\n\r\n6. Increase the firefighting dedicated water tank capacity to 30 m³.\r\n\r\n7. Provide an emergency evacuation plan and install exit signs.\r\n\r\n8. Provide one additional 9kg CO₂ fire extinguisher.\r\n\r\n9. Restock the First Aid kit with all required items.\r\n\r\n10. Avail the following documents: Occupation Permit, Retail License, and Valid Insurance.\r\n\r\n11. Remove LPG gas cylinder obstructing the fire hydrant.\r\n\r\n12. Provide separate changing rooms for men and women.\r\n\r\n13. Display warning signs at the fuel storage tank.\r\n\r\n14. Conduct general cleaning in the washroom, specifically removing unused and scattered materials.\r\n\r\n15. Install a handwashing facility at the entrance.', NULL, NULL, 67.00, 100.00, 67.00, NULL, NULL, NULL, NULL, '2026-08-10 07:39:42', '2026-08-10 07:39:42', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(31, NULL, 27, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 8, 'NITINGENERA Thierry', 1, 'The petrol staton is non compliant.', '1. To do maintenance of water pump (as of now it is not working)\r\n2. To refill expired fire extinguishers\r\n3. To make the back up generator automatically operated whenever there is power outage\r\n4. To provide fully equipped first aid kit\r\n5. To increase the capacity of water reservoirs to at least 30 m³\r\n6. To provide (insurance, tank calibration certificate, and retail license) via email and electrical installation compliance certificate', NULL, NULL, 62.00, 99.00, 62.63, NULL, NULL, NULL, NULL, '2026-08-10 07:46:38', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(32, NULL, 28, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'station is not complying with fire safety and security', '1. Upgrade CCTV camera storage to retain footage for at least 3 months / 90 days.\r\n\r\n2. Install a fire pump with a minimum pressure of 8 bar and repair the damaged fire hydrant.\r\n\r\n3. Repair and maintain the fire alarm system.\r\n\r\n4. Test the lightning protection system every 6 months by a professional engineer.\r\n\r\n5. Display illuminated entrance and exit signs and designate assembly points.\r\n\r\n6. Increase the firefighting dedicated water tank capacity to 30 m³.\r\n\r\n7. Provide an emergency evacuation plan and install exit signs.\r\n\r\n8. Provide an additional 25kg ABC fire extinguisher.\r\n\r\n9. Restock the First Aid kit with all required items.\r\n\r\n10.Regulate parking at the station  the number of cars exceeds the recommended limit. _Maximum allowed: 5 cars_.\r\n\r\n11. Provide separate changing rooms for men and women.\r\n\r\n12. Display warning signs at the fuel storage tank.\r\n\r\n13. Conduct general cleaning of water drainage channels by removing all waste dumped inside.\r\n\r\n14. Provide separate washrooms for males and females.\r\n\r\n15. Remove stagnant water around the changing rooms.\r\n\r\n16. Mount fire extinguishers currently placed on the floor.\r\n\r\n17. Provide a sheltered waste collection corner and provide covered dustbins.\r\n\r\n18. Install a handwashing facility at the entrance, increase the number of dustbins, and maintain regular cleaning.', NULL, NULL, 64.00, 100.00, 64.00, NULL, NULL, NULL, NULL, '2026-08-10 07:56:11', '2026-08-10 07:56:11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(33, NULL, 29, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'the station is not complying with fire safety and security system', '1.Upgrade the CCTV storage system to retain footage for at least 3 months / 90 days.\r\n\r\n2. Increase fire pump capacity to a minimum of 8 bar.\r\n\r\n3. Test the lightning protection system every 6 months by a professional engineer and obtain the test report.\r\n\r\n4. Refill expired fire extinguishers and provide additional firefighting equipment: one 9kg CO₂ fire extinguisher.\r\n\r\n5. Display an emergency evacuation plan and install exit signs.\r\n\r\n6. Remove all waste materials stored around the generator house.\r\n\r\n7. Restock the First Aid kit with missing items.\r\n\r\n8. Replace small shovels in the sand box with larger ones.\r\n\r\n9. Remove scattered waste materials around the station and other areas.\r\n\r\n10. Provide adequate dustbins and designate a waste collection corner.\r\n\r\n11. Provide handwashing facilities at the entrance.\r\n\r\n12. Install a pedal dustbin in the female washroom.\r\n\r\n13. Avail the following documents: Valid Insurance and Retail License.', NULL, NULL, 61.00, 100.00, 61.00, NULL, NULL, NULL, NULL, '2026-08-10 08:13:51', '2026-08-10 08:13:51', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(34, NULL, 30, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To maintain water based firefighting system by increasing water pressure in fire hydrant to ensure it is fully operational.\r\nb. To increase the water reserve tank capacity to a minimum of 30 m³.\r\nc. To maintain or replace fire alarm system control panel.\r\nd. To display emergency evacuation plan.\r\ne. To increase the storage capacity of CCTV cameras in order to retain footage for at least three (3) months.\r\nf. To install a dedicated circuit breaker for each fuel dispenser, provide an emergency stop switch, and install a lightning protection system.\r\nf. To carry out maintenance of generator and ensure that it operates automatically.\r\ng. To avail at least two (2) changing room. \r\nh. To send electrical installation compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, dispenser test certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw within two weeks.', NULL, NULL, 40.00, 100.00, 40.00, NULL, NULL, NULL, NULL, '2026-08-10 08:35:28', '2026-08-11 08:47:16', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(35, NULL, 31, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'the station is not complying with fire safety and security system', '1. Upgrade CCTV camera storage to retain footage for at least 3 months / 90 days.\r\n\r\n2. Increase fire pump pressure to a minimum of 8 bar.\r\n\r\n3. Repair and maintain the fire alarm system and ensure it is working properly.\r\n\r\n4. Test the lightning protection system every 6 months by a professional engineer.\r\n\r\n5. Display illuminated entrance and exit signs.\r\n\r\n6.Remove all stored materials around the generator house and install a 5kg CO₂ fire extinguisher* inside the generator room.\r\n\r\n7. Increase the firefighting dedicated water tank* capacity to 30 m³. _The water tank must have 30 m³._\r\n\r\n8. Provide an emergency evacuation plan and install exit signs.\r\n\r\n9. Avail the following mandatory documents: Occupation Permit, Retail License, and Valid Insurance.\r\n\r\n10. Restock the First Aid kit with missing items.\r\n\r\n11. Install a hand dryer in the washroom.\r\n\r\n12. Provide a pedal dustbin in the female washroom.\r\n\r\n13. Conduct general cleaning in the room next to the \"Grab and Go\" retail shop and clean the stairs.\r\n\r\n14. Clean the room currently used as a changing room and provide separate changing rooms for men and women', NULL, NULL, 59.00, 100.00, 59.00, NULL, NULL, NULL, NULL, '2026-08-10 08:37:52', '2026-08-10 08:37:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(36, NULL, 32, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, 'The petrol station is found to be non compliant', '1. To provide additional 1 piece of 2kg DCP fire extinguisher.\r\n2. ​To increase storage capacity of CCTV cameras to 3 months (minimum storage).\r\n3. Tor​Refill expired fire extinguishers.\r\n4. ​To mark clearly exit and entrance.\r\n5. ​To install fully functional water-based firefighting system (tank 30 m³, pump, hose reels, and hydrant).', NULL, NULL, 77.00, 100.00, 77.00, NULL, NULL, NULL, NULL, '2026-08-10 08:39:20', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(37, NULL, 33, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, NULL, '1.	to add fire extinguisher( 1 of foam with 9kgs,1 of powder with 25kgs)\r\n2.	to repair fire alarm control system\r\n3.	to put Emergency evacuation plan in their places for smooth movements\r\n4.	to display Emergency hotline in in all possible places for Emergency responses.\r\n5.	to install cctv camera system which cover the entire compound with 3-month storage capacity\r\n6.	To display Warning notices and pictograms boldly on canopy columns, vent pipes, and storage tank areas.\r\n7.	To have visible and readable from a minimum distance of 7.5 meters around the compound\r\n8.	Display illuminated/retro-reflective, readable Entrance and exit signs\r\n9.	To find a valid electrical installation certificate and provide it one inspection email:inspection@gasabo.gov.rw\r\n10.	send Fuel tank calibration certificate on inspection email:inspection@gasabo.gov.rw\r\n11.	provide Dispensers and safety/security equipment on above Email within 2 weeks\r\n12.	provide Retail license on above Email within 2 weeks\r\n13.	provide Valid Insurance on above email within 2 weeks\r\n14.	To remove Kitchen in the compound of petrol station', NULL, NULL, 74.00, 100.00, 74.00, NULL, NULL, NULL, NULL, '2026-08-10 08:48:10', '2026-08-10 08:48:10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(38, NULL, 34, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, NULL, '1	Replace the overcharged 25 kg extinguisher and provide one 9 kg foam extinguisher and one 25 kg dry powder extinguisher.\r\n2	Ensure the plot size meets the minimum requirement of 1,500 m².\r\n3	Provide one shovel at each dustbin.\r\n4	Install and fully restore the fire alarm control system, control panel, and all associated accessories.\r\n5	Install emergency evacuation plans, emergency assembly point signs, and emergency hotline information at appropriate locations.\r\n6	Provide a 30 m³ firefighting water tank and a firefighting pump with a pressure of at least 8 bar.\r\n7	Install a CCTV camera system covering the entire compound with at least 3 months of storage capacity.\r\n8	Provide a fully stocked and easily accessible first aid kit on the compound.\r\n9	Deploy trained security staff from a registered security company at the station.\r\n10	Display warning notices and pictograms prominently on canopy columns, vent pipes, and storage tank areas, ensuring visibility and readability from at least 7.5 m.\r\n11	Install illuminated/retro-reflective and clearly readable entrance and exit signs.\r\n12	Install an isolating circuit breaker for the dispenser circuit and an emergency stop switch for the entire electrical system.\r\n13	Install an automatic power backup system to ensure continuous power supply.\r\n14	Ensure all electrical installations are carried out by certified electrical practitioners.\r\n15	Submit the fuel tank calibration certificate, retail license, and valid insurance to inspection@gasabo.gov.rw within two weeks.', NULL, NULL, 55.00, 100.00, 55.00, NULL, NULL, NULL, NULL, '2026-08-10 08:57:15', '2026-08-10 10:41:43', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(39, NULL, 35, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'the petrol station is not complying with fire safety and security', '1.To Upgrade CCTV cameras to retain footage for at least 3 months.\r\n\r\n\r\n\r\n2.to  Install a fully functional water-based firefighting system including:\r\n\r\n   Fire pump with minimum pressure of 8 bar\r\n\r\n    Increase capacity of firefighting water tank to 30 m³\r\n\r\n\r\n\r\n3. to Test the lightning protection system every 6 months by a professional engineer.\r\n\r\n\r\n\r\n4. To Remove all materials stored around the generator room  and install 5kg CO₂ fire extinguishers.\r\n\r\n\r\n\r\n5. to Remove car parking that obstructs emergency assembly points. \r\n\r\n   Also display emergency exit signs and display emergency response phone numbers.\r\n\r\n\r\n\r\n6. To Repair the fire alarm system including the control panel.\r\n\r\n\r\n\r\n7. to Provide shovels  in the sand box.\r\n\r\n\r\n\r\n8. to Avail the following documents: Retail license, Insurance, and Occupation permit.\r\n\r\n\r\n\r\n9. to Repair hand dryers in the washroom.\r\n\r\n\r\n\r\n10. to Provide pedal dustbins and improve hygiene. Repair existing dustbins and display signage for male and female toilets.', NULL, NULL, 72.00, 100.00, 72.00, NULL, NULL, NULL, NULL, '2026-08-10 09:04:04', '2026-08-13 06:36:42', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(40, NULL, 36, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install one (1) additional 9 kg foam fire extinguisher and one (1) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb. To increase water pressure in fire hydrants and hose reel by maintaining/replacing water pressure pump to ensure they are fully operational.\r\nc. To increase the water reserve tank capacity to a minimum of 30 m³.\r\nd. To maintain or replace fire alarm system control panel.\r\ne. To display emergency evacuation plan.\r\nf. To increase the storage capacity of CCTV camera in order to retain footage for at least three (3) months.\r\ng. To provide entrance and exit signs using illuminated or retro-reflective materials, clearly readable from a minimum distance of 50 m.\r\nh. To carry out maintenance of generator and ensure that it operates automatically.\r\ni. To avail at least two changing room.\r\nj. To conduct lightning protection system testing every six (6) months and maintain proper test records for verification during inspections.\r\nk. To stop gas sales and filling operations and prohibit welding activities at the rear of the petrol station.\r\nl. To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, Dispenser test certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw within two weeks.', NULL, NULL, 51.00, 100.00, 51.00, NULL, NULL, NULL, NULL, '2026-08-10 09:04:30', '2026-08-11 11:19:19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(41, NULL, 37, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, NULL, '1. To provide  Entrance and exit signs illuminated/retro-reflective, readable from a minimum distance of 50 meters \r\n2. To do maintenance for water based fire fighting system (tanks of 30m³, pump of 8 bars, hose reel and fire hydrant).\r\n3. To provide additional fire extinguishers (2 pieces of 5kg of CO₂, 1 piece of 25kg of DCP).\r\n4. To do maintenance of fire alarm system and control panel.\r\n5. To increase storage capacity of CCTV cameras to at least 3 months.\r\n6. To provide occupation permit, EIA certificate and via email.\r\n7. To provide and mount siigns for emergency phone numbers', NULL, NULL, 69.50, 99.00, 70.20, NULL, NULL, NULL, NULL, '2026-08-10 09:47:44', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(42, NULL, 38, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'the station Do not complying with fire safety and security system', '1. Install a fully functional water-based firefighting system. \r\n    Increase fire pump pressure to at least 8 bar.\r\n    Repair fire hydrants with 45mm hose diameter.\r\n    Provide a dedicated water storage tank for firefighting of at least 30 m³.\r\n\r\n2. Upgrade CCTV system.\r\n    Increase camera storage capacity to 90 days (3 months).\r\n\r\n3. Mount fire extinguishers properly.\r\n    Remove extinguishers placed on the floor.\r\n    Provide additional extinguishers: 9kg CO₂ and 2kg dry chemical powder (DCP) fire extinguishers.\r\n\r\n4. Test lightning protection system.\r\n   Obtain a valid test certificate every 6 months.\r\n    Testing to be done by a qualified professional engineer.\r\n\r\n5. Provide shovels in the sand box.\r\n\r\n6. Display emergency signage.\r\n    Emergency exit signs, evacuation floor plan, and assembly point signs.\r\n\r\n7. Conduct an electrical installation audit.\r\n    Obtain a compliance certificate.\r\n\r\n8. Remove stored materials from the generator room.\r\n\r\n9. Provide changing rooms.\r\n    Separate facilities for both male and female staff.\r\n    Remove wasted/unused items and utilize available space.\r\n\r\n10. Remove car parking near the fuel storage tank.', NULL, NULL, 71.00, 100.00, 71.00, NULL, NULL, NULL, NULL, '2026-08-10 10:15:42', '2026-08-13 06:57:41', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(43, NULL, 39, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, NULL, '1. To  providde At least two (2) changing rooms\r\n2. To provide sanitary facilities for people with disabilities ( 1 toilet with urinals for males and  1 toilet for females \r\n3.  To install enough CCTV Cameras and Control Room with storage capacity of 3 months.\r\n4. To provide 3 pieces of 5kg CO₂ and 8 pieces of 25kg DCP fire extinguishers.\r\n5. To install water-based firefighting system (a tank of 30m³, pump, 3 hoses, hose reel and hydrant).\r\n6. To do maintenance of fire alarm system.\r\n7. To provide calibration certificate, EIA, retail license, electrical installation certificate, and insurance via email.\r\n8. To provide and mount assembly point, emergency response unit phone numbers.\r\n9. To install a para lightning system that covers the entire station buildings.', NULL, NULL, 47.50, 99.00, 47.98, NULL, NULL, NULL, NULL, '2026-08-10 10:18:25', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(44, NULL, 40, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install one (1) additional 9 kg foam fire extinguisher and one (1) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb. To repair and maintain water based firefighting system (fire hydrants, hose reel, and water pressure pump) to ensure they are fully operational.\r\nc. To increase the water reserve tank capacity to a minimum of 30 m³.\r\nd. To maintain or replace fire alarm system control panel.\r\ne. To display emergency evacuation plan and avail emergency assembly point with signs.\r\nf. To increase the storage capacity of CCTV cameras in order to retain footage for at least three (3) months.\r\nj. To conduct lightning protection system testing every six (6) months and maintain proper test records for verification during inspections.\r\nk. To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, dispenser test certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw within two weeks.', NULL, NULL, 51.50, 100.00, 51.50, NULL, NULL, NULL, NULL, '2026-08-10 10:32:12', '2026-08-11 12:37:47', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(45, NULL, 41, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'the petrol station is not complying with fire and security system', '1. Install a fully functional water-based firefighting system.\r\n    Hose reel: 30m length\r\n    Fire hydrant: hose diameter 45mm.\r\n    Fire pump: minimum pressure of 8 bar.\r\n    Water tank: minimum capacity of 30 m³.\r\n\r\n2. Test lightning protection system.\r\n    Obtain a valid test report every 6 months.\r\n    Testing to be carried out by a qualified professional engineer.\r\n\r\n3. Conduct an electrical installation audit.\r\n    Obtain a compliance certificate.\r\n\r\n4. Upgrade CCTV system.\r\n    Camera storage to retain footage for at least 3 months.\r\n\r\n5. Repair fire alarm system.\r\n    Including manual call points.\r\n\r\n6. Remove car parking at the station.\r\n    Maximum parking stalls should not exceed the approved number.\r\n\r\n7. Provide emergency procedures.\r\n    Display evacuation plan, emergency phone numbers: Fire Brigade, Ambulance, and Police.\r\n    Remove obstructions at assembly points.\r\n\r\n8. Provide additional fire safety equipment.\r\n    Provide additional 9kg CO₂ fire extinguishers.\r\n    Mount fire extinguishers properly. Remove those placed on the floor.\r\n\r\n9. Remove kitchen operations from the station.\r\n    Stop all related food preparation activities at the station.\r\n\r\n10. Avail the following documents:\r\n     Valid insurance, retail license, and occupancy permit.\r\n\r\n11. Improve general hygiene.\r\n     Clean the room where fire extinguishers are stored.\r\n     Provide dustbins and washing facilities.', NULL, NULL, 66.00, 100.00, 66.00, NULL, NULL, NULL, NULL, '2026-08-10 10:39:29', '2026-08-13 07:28:44', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(46, NULL, 42, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, NULL, '1. To install water-based firefighting system (tank of 30 m³ + pump + 8 hoses, hose reels and fire hydrant).\r\n2. To revise fire alarm system and control panel to make it fully functional.\r\n3. To provide additional fire extinguishers (1 piece of 25kg DCP, 2 pcs of 5kg CO₂, and 2 pieces of 9kg Foam).\r\n4. To increase storage capacity of CCTV cameras to 3 months.\r\n5. To place an assembly point sign post where visible.\r\n6. To mount evacuation plans and emergency phone numbers.\r\n7. To refill expired fire extinguishers.', NULL, NULL, 59.00, 99.00, 59.60, NULL, NULL, NULL, NULL, '2026-08-10 10:51:18', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(47, NULL, 43, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'The station is not complying with fire safety and security system', '1. Increase water pump capacity\r\n   Achieve minimum pressure of 8 bar for the fire pump.\r\n\r\n2. Increase water storage for firefighting \r\n   Provide a water tank of up to 30 m³. \r\n    Repair damaged hose reels.\r\n\r\n3. Upgrade CCTV system\r\n    Camera storage to retain footage for at least 90 days (3 months).\r\n\r\n4. Repair fire alarm system \r\n    The current system is not working.\r\n\r\n5. Test lightning protection system\r\n    Conduct tests every 6 months and obtain a test report.\r\n\r\n6. Avail required documents\r\n    Submit occupancy permit and retail license.\r\n\r\n7. Conduct electrical installation audit\r\n    Obtain a valid electrical installation compliance certificate.\r\n\r\n8. Display emergency procedures\r\n    Post emergency evacuation plan, clear exit signs, and adequate warning notices.\r\n\r\n9. Provide additional fire extinguishers\r\n    Provide additional 9kg CO₂ and 2kg DCP fire extinguishers.\r\n\r\n10. Improve waste management\r\n     Collect all solid waste scattered at the station, around the pump, and near the drainage channel. \r\n     Dump waste in an appropriate waste area. \r\n     Provide enough dustbins (pedal dustbin).\r\n\r\n11. Provide separate sanitation facilities\r\n     Provide separate toilets for men and women', NULL, NULL, 69.00, 100.00, 69.00, NULL, NULL, NULL, NULL, '2026-08-10 11:06:32', '2026-08-13 06:16:26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(48, NULL, 44, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, NULL, '1      Ensure the plot size meets the minimum requirement of 1,500 m².\r\n2	Provide a 25 kg powder fire extinguisher and repair the fire alarm control system.\r\n3	Install and properly display emergency evacuation plans and hotline numbers at visible locations.\r\n4	Install a water-based firefighting system with a pump pressure of at least 8 bar.\r\n5	Install a CCTV system covering the entire compound with 3-month recording storage.\r\n6	Provide visible and readable safety/signage around the compound, readable from at least 7.5 m.\r\n7	Install an isolating circuit breaker for the dispenser circuit.\r\n8	Obtain and submit the valid electrical installation certificate and fuel tank calibration certificate to inspection@gasabo.gov.rw.\r\n9	Submit dispenser and safety/security equipment documents, retail license, and valid insurance to the inspection email within 2 weeks.\r\n10	Comply with the applicable zoning regulations and obtain the required approvals.\r\n11	Remove the kitchen from the petrol station compound.', NULL, NULL, 54.00, 100.00, 54.00, NULL, NULL, NULL, NULL, '2026-08-10 11:13:11', '2026-08-11 11:06:30', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(49, NULL, 45, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, NULL, '1. To do maintenance of water-based firefighting system to make it fully functional(tank should be 30 m³, pump should be 8 bars).\r\n2. To increase storage capacity of CCTV cameras to 3 months.\r\n3. To provide additional fire extinguishers (at least, 1 piece of 25kg DCP, 2 pieces of 5kg CO₂ and 2 pieces of 9kg foam type).\r\n3. To test the paralightning system regularly every six months and keep results records.\r\n4. To provide electrical installation compliance certificate, calibration certificate and retail certificate via email( inspection@gasabo.gov.rw)\r\n5. To provide a fire extinguisher of CO₂, 5kg in offices.', NULL, NULL, 59.00, 99.00, 59.60, NULL, NULL, NULL, NULL, '2026-08-10 11:18:37', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(50, NULL, 45, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 2, 'completed', 8, 'NIYINGENERA Thierry', 1, NULL, '1. To do maintenance of water-based firefighting system to make it fully functional(tank should be 30 m³, pump should be 8 bars).\r\n2. To increase storage capacity of CCTV cameras to 3 months.\r\n3. To provide additional fire extinguishers (at least, 1 piece of 25kg DCP, 2 pieces of 5kg CO₂ and 2 pieces of 9kg foam type).\r\n3. To test the paralightning system regularly every six months and keep results records.\r\n4. To provide electrical installation compliance certificate, calibration certificate and retail certificate via email( inspection@gasabo.gov.rw)\r\n5. To provide a fire extinguisher of CO₂, 5kg in offices.', NULL, NULL, 59.00, 99.00, 59.60, NULL, NULL, NULL, NULL, '2026-08-10 11:18:38', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(51, NULL, 46, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install one (1) additional 9 kg foam fire extinguisher and one (1) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb. To repair and maintain water based firefighting system (fire hydrants, hose reel, and water pressure pump) to ensure they are fully operational.\r\nc. To increase the water reserve tank capacity to a minimum of 30 m³.\r\nd. To display emergency evacuation plan and emergency assembly point.\r\ne. To increase the storage capacity of CCTV cameras in order to retain footage for at least three (3) months.\r\nf. To display entrance and exit signs using illuminated retro-reflective material readable from a minimum distance of 50 meters.\r\ng.  To carry out maintenance of generator and ensure that it operates automatically.\r\nh. To conduct lightning protection system testing every six (6) months and maintain proper test records for verification during inspections.\r\ni. To ensure that the toilet for persons with disabilities is accessible and to provide at least two changing rooms.\r\nj. To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw', NULL, NULL, 48.00, 100.00, 48.00, NULL, NULL, NULL, NULL, '2026-08-10 11:19:16', '2026-08-11 14:56:36', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(52, NULL, 47, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install one (1) additional 9 kg foam fire extinguisher, one (1) additional 9 kg Co2 fire extinguisher and one (1) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb. To repair and maintain water based firefighting system (fire hydrants, hose reel, and water pump) to ensure they are fully operational.\r\nc. To increase the water reserve tank capacity to a minimum of 30 m³.\r\nd. To avail dry fine sand with two shovels\r\ne. To maintain or replace fire alarm system with control panel.\r\nf. To display emergency evacuation plan.\r\ng. To increase the storage capacity of CCTV cameras in order to retain footage for at least three (3) months.\r\nh. To avail first aid kit.\r\ni. To install lightning protection system and test it every six (6) months and maintain proper test records for verification during inspections.\r\nj. To avail toilets for male (1 toilet with urinals), 1 toilet female, and 1 toilet for persons with disabilities and two changing rooms.\r\nk. To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw within two weeks', NULL, NULL, 49.50, 100.00, 49.50, NULL, NULL, NULL, NULL, '2026-08-10 11:26:52', '2026-08-19 05:32:34', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `inspections` (`id`, `case_reference`, `entity_id`, `template_id`, `type_code`, `stage`, `permit_number`, `application_number`, `permit_issued_on`, `reviewed_on`, `permit_expiry`, `contractor`, `supervisor`, `building_status`, `dwelling_unit`, `has_physical_plan`, `building_category`, `on_main_corridor`, `corridor_road`, `inspection_date`, `visit_type`, `previous_inspection_id`, `visit_number`, `status`, `inspector_id`, `inspector_name`, `district_id`, `observations`, `recommendations`, `owner_recommendations`, `owner_rep_name`, `earned_score`, `possible_score`, `compliance`, `legacy_id`, `deleted_at`, `deleted_by`, `deleted_reason`, `created_at`, `updated_at`, `occupation_permit_number`, `occupation_permit_year`, `manager_name`, `manager_telephone`, `wastewater_system_type`, `wastewater_system_type_other`, `stp_type`, `stp_type_other`, `design_capacity_m3`, `population_served`, `water_consumption_m3`, `year_constructed`, `last_maintenance_date`, `last_desludging_date`, `desludging_frequency`, `operational_status`, `stp_general_condition`, `effluent_test_date`, `laboratory_name`, `final_discharge_point`, `septic_tank_type`, `septic_chamber_count`, `septic_tank_material`, `septic_tank_capacity`, `septic_year_installed`, `distance_to_foundation_m`, `septic_tank_location`, `absorption_field_condition`, `effluent_disposal_method`, `desludging_provider`, `tank_adequacy`, `septic_observations`, `non_compliances`, `non_compliances_other`, `key_findings`, `environmental_risks`, `wastewater_compliance_status`, `decision_taken`, `wastewater_fine_amount`, `wastewater_compliance_deadline`, `wastewater_followup_date`) VALUES
(53, NULL, 48, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'petrol station is not complying with fire safety and security system', '1. Test lightning protection system\r\n   Conduct testing every 6 months by a qualified professional engineer.\r\n\r\n2. Increase fire pump capacity\r\n   Achieve a minimum pressure of 8 bar.\r\n\r\n3. Mount fire extinguishers properly  \r\n   Remove extinguishers currently placed on the floor.  \r\n   Provide additional 9kg CO₂ and 2kg DCP fire extinguishers.\r\n\r\n4. Repair fire alarm system \r\n   Including manual call points which are not emitting a signal.\r\n\r\n5. Avail required documents\r\n   Submit valid Retail License, Insurance Certificate, and Occupancy Permit.\r\n\r\n6. Remove waste and stored materials \r\n   Clear all waste and materials stored in the generator house.\r\n\r\n7. Display emergency signage  \r\n   Install illuminated entrance and exit signs.\r\n\r\n8. Upgrade CCTV system  \r\n   Upgrade camera storage to retain footage for up to 3 months.  \r\n   Repair the camera that is not working.\r\n\r\n9. Display notice on washrooms  \r\n   Clearly indicate separate toilets for men and women.\r\n\r\n10. Provide changing rooms\r\n    Provide separate changing rooms for both male and female staff.\r\n\r\n11. Improve hygiene and waste management\r\n    Improve hygiene around the petrol station.  \r\n    Provide enough pedal dustbins, hand washing basins at the station, and a designated waste disposal area.', NULL, NULL, 70.00, 100.00, 70.00, NULL, NULL, NULL, NULL, '2026-08-10 11:34:08', '2026-08-10 11:34:08', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(54, NULL, 49, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, NULL, NULL, NULL, NULL, 69.00, 98.00, 70.41, NULL, NULL, NULL, NULL, '2026-08-10 11:34:29', '2026-09-08 07:06:15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(55, NULL, 50, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, NULL, '1.	Fire & Security Systems: Expedite building repairs to restore full functionality to the fire alarm control panel and CCTV system.\r\n2.	Emergency Preparedness: Display emergency contact numbers and evacuation plan diagrams in designated, visible locations.\r\n3.	Emergency Controls: Re-enable and test the master emergency stop switch upon completion of building repairs.\r\n4.	Firefighting Infrastructure: Install a water-based firefighting system equipped with a $30\\text{ m}^3$ water storage tank, a 2-bar water pump, hose reels, and fire hydrants covering the entire compound.\r\n5.	Document Submission: Email copies of the insurance policy, electrical compliance certificate, retail license, and fuel tank calibration certificate to inspection@gasabo.gov.rw.', NULL, NULL, 57.50, 100.00, 57.50, NULL, NULL, NULL, NULL, '2026-08-10 11:41:17', '2026-08-10 11:47:56', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(56, NULL, 49, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 2, 'completed', 8, 'NIYINGENERA Thierry', 1, NULL, '1. To install fully functional water-based firefighting system (water tank of 30m³, pump of 8 bars, hose reel and fire hydrant).\r\n2. To install fire alarm system that covers all buildings (composed of smoke detectors, control panel and manual call points).\r\n3. To provide additional fire extinguishers (1 piece of 25kg DCP, 2 pieces of 5kg of CO₂ and 2 pieces of 9kg of foam).\r\n4. To install paralightning system that covers the whole compound and premises.\r\n5. To revise electrical installation and obtain electrical installation compliance certificate.\r\n6. To install emergency stop button (switch).\r\n7. To identify and mark assembly points, entrance and exit, emergency contacts.\r\n8. To provide retail license, occupation permit and calibration certificate via email.', NULL, NULL, 70.50, 99.00, 71.21, NULL, NULL, NULL, NULL, '2026-08-10 11:49:52', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(57, NULL, 51, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'the facility do not comply with fire safety and security system', '1. Install a fully functional water-based firefighting system.\r\n    Increase fire pump pressure to at least 8 bar\r\n    Repair fire hydrants with short 45-70mm hoses\r\n    Provide a dedicated water storage tank for firefighting with a capacity of 30 m³\r\n\r\n2. Upgrade CCTV camera storage to retain footage for up to 90 days (3 months).\r\n\r\n3. Mount fire extinguishers that are currently placed on the floor, and provide additional units: \r\n    9kg CO₂ extinguishers \r\n    kg ABC dry powder fire extinguishers\r\n\r\n4.Test the lightning protection syste and obtain a valid test report valid for 6 months. \r\n   _To be conducted by a professional engineer._\r\n\r\n5. Provide shovels in the sand box.\r\n\r\n6. Display emergency exit signs, entrance signs, and assembly point signs.\r\n\r\n7. Conduct an electrical installation audit and obtain a compliance certificate.\r\n\r\n8. Remove all stored materials from the generator room.\r\n\r\n9. Provide changing rooms for both male and female staff, and remove waste currently stored in the available changing room', NULL, NULL, 71.00, 100.00, 71.00, NULL, NULL, NULL, NULL, '2026-08-10 12:08:12', '2026-08-13 07:16:01', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(58, NULL, 52, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, NULL, '1. To Install enough CCTV cameras with control room with storage capacity of 3 months.\r\n2. To install water-based firefighting system (water tank of 30m³, pump of 8 bars, hose reels and fire hydrant).\r\n3. To provide enough fire extinguishers (two pieces of 25kg DCP, 2 pieces of 5kg CO₂ and two pieces of 9kg foam).\r\n4. To provide and install automatic backup generator.\r\n5. To install fully functional fire alarm system (smoke detectors, control panel and manual call points).\r\n6. To install emergency stop switch.\r\n7. To mount evacuation plans, assembly points, emergency phone numbers.\r\n8. To provide first aid boxes (fully equipped).\r\n9. To hire a professional security staff from registered security company.\r\n10. To provide electrical installation compliance certificate, calibation certificate, retail licence and occupation permit via email\r\n11. To provide  Entrance and exit signs illuminated/retro-reflective, readable from a minimum distance of 50 meters', NULL, NULL, 45.50, 99.00, 45.96, NULL, NULL, NULL, NULL, '2026-08-10 12:08:31', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(59, NULL, 53, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, NULL, '1. Fire Alarm System: Activate the fire alarm control system (the control panel was found in the \"OFF\" position).\r\n2. Water-Based Firefighting System: Repair the water-based firefighting system (there is currently no water output at the hydrants and hose reels).\r\n 3. CCTV Security: Increase CCTV camera system storage capacity to retain footage for a minimum of 3 months.\r\n4. Compliance Documentation: Submit copies of the following documents via email to inspection@gasabo.gov.rw:\r\n•	Electrical Installation Certification\r\n•	Valid Insurance Certificate\r\n•	Retail License\r\n•	Fuel Tank Calibration Certificate\r\n•	Valid Dispensers Certification', NULL, NULL, 75.50, 100.00, 75.50, NULL, NULL, NULL, NULL, '2026-08-10 12:13:47', '2026-08-10 12:13:47', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(60, NULL, 54, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, NULL, '•  1. Water-Based Firefighting System: Increase the system water pressure (currently found at a low level) and expand the water storage tank capacity up to 30metr cube.\r\n•  2. CCTV Security: Increase CCTV camera system storage capacity to retain footage for a minimum of 3 months.\r\n•  3. Fire Extinguishers: Acquire/install an additional 25kgfire extinguisher.\r\n•  4. Compliance Documentation: Submit copies of the following documents via email to inspection@gasabo.gov.rw:\r\n•	Electrical Installation Certificate\r\n•	Insurance Policy\r\n•	Fuel Tank Calibration Certificate\r\n•	Retail License\r\n•  5. Facility Layout / Hazard Mitigation: Remove the kitchen currently set up within 30m of the main pumping station.', NULL, NULL, 67.00, 100.00, 67.00, NULL, NULL, NULL, NULL, '2026-08-10 12:23:20', '2026-08-10 12:40:06', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(61, NULL, 55, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'the petrol station do not comply with fire safety and security system', '1. Test the lightning protection system every 6 months by a professional engineer.\r\n2. Increase fire pump capacity to at least 8 bar.\r\n3. Mount fire extinguishers that are currently placed on the floor, and provide additional units:\r\n   9kg CO₂ fire extinguishers\r\n    6kg ABC dry powder fire extinguishers\r\n4. Repair the fire alarm system, including the manual call point which is not emitting a signal.\r\n5. Avail the following documents: Retail license, valid insurance, and occupation permit.\r\n6. Remove all waste and materials stored in the generator house.\r\n7. Display illuminated entrance and exit signs.\r\n8. Upgrade CCTV camera storage to retain footage for up to 3 months, and repair the camera that is not working.\r\n9.Display signage on the washroom indicating separate toilets for men and women.\r\n10. Provide separate changing rooms for both male and female staff', NULL, NULL, 53.00, 100.00, 53.00, NULL, NULL, NULL, NULL, '2026-08-10 12:30:11', '2026-08-13 07:00:42', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(62, NULL, 56, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install one (1) additional 9 kg foam fire extinguisher and one (1) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb. To repair and maintain water based firefighting system (fire hydrants and hose reel) to ensure they are fully operational.\r\nc. To increase the water reserve tank capacity to a minimum of 30 m³.\r\nd. To install Water pressure pump of at least 8 bar.\r\ne. To maintain or replace fire alarm system with control panel.\r\nf. To avail dry sand with two shovels.\r\ng. To maintain the CCTV system and increase its storage capacity to ensure that surveillance footage is retained for at least three (3) months.\r\nh. To install emergency stop switch.\r\ni. To provide an accessible toilet for persons with disabilities and an additional changing room.\r\nj.   To accelerate the installation of the lightning protection system and ensure its timely completion and conduct it testing every six (6) months and maintain proper test records for verification during inspections.\r\nk. To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw within two weeks.', NULL, NULL, 51.50, 100.00, 51.50, NULL, NULL, NULL, NULL, '2026-08-10 12:37:47', '2026-08-26 06:55:15', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(63, NULL, 57, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, 'The petrol station was found to be non compliant', '1. To increase storage capacity of CCTV cameras to 3 months.\r\n2. To do maintenance of water-based firefighting system (pump 8 bar fitted, and increase water reservoir to 30 m³ dedicated for firefighting).\r\n3. To provide additional fire extinguishers (one 10kg dry powder, 2 pcs 9kg foam and 1 pc 5kg CO₂).\r\n4. To mount emergency phone numbers and assembly point.\r\n5. To provide retail license via email.\r\n6.  The backup generator is manually operated, it needs to be made automatic.', NULL, NULL, 93.00, 99.00, 93.94, NULL, NULL, NULL, NULL, '2026-08-10 12:47:35', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(64, NULL, 58, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, NULL, '1.Water-Based Firefighting System: Install a water-based firefighting system complete with a 30m3 water tank, a 2-bar water pump, hose reels, and hydrants covering the entire station.\r\n2.Fire Alarm System: Install a fire alarm system with a central control panel.\r\n3.Safety Signage & Markings: Mount assembly point signs, emergency contact numbers, and warning signboards in their appropriate locations to ensure smooth movement.\r\n4.Documentation Submission: Send copies of the following documents via email to inspection@gasabo.gov.rw:\r\n•	Electrical Installation Certificate\r\n•	Valid Insurance Policy\r\n•	Retail License\r\n•	Fuel Tank Calibration Certificate\r\n5.Fire Extinguishers: Ensure the facility is equipped with fire extinguishers, including 9 kg powder, 9 kg CO2, and 25 kg powder units.\r\n6.CCTV Security System: Install a CCTV camera system with storage capacity for at least 3 months of video footage.', NULL, NULL, 45.00, 100.00, 45.00, NULL, NULL, NULL, NULL, '2026-08-10 13:00:11', '2026-08-10 13:00:12', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(65, NULL, 59, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install one (1) additional 9 kg foam fire extinguisher, one (1) additional 9 kg Co2 fire extinguisher and two (2) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb. To install Water pressure pump of at least 8 bar.\r\nc. To increase the water reserve tank capacity to a minimum of 30 m³.\r\nd. To install fire alarm system with control panel.\r\ne. To avail first aid kit and trained security staff from registered security company.\r\nf. To display emergency evacuation plan, emergency assembly point, and emergency hotline.\r\ng. To maintain CCTV cameras and increase their storage capacity in order to retain footage for at least three (3) months.\r\nh. To display entrance and exit using retro-reflective material.\r\ni. To install emergency, stop switch, automatic power backup system (generator), and lightning protection system.\r\nj. To avail toilet for person with disabilities.\r\nk. To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw', NULL, NULL, 57.50, 100.00, 57.50, NULL, NULL, NULL, NULL, '2026-08-10 13:10:23', '2026-08-10 13:10:23', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(66, NULL, 59, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 2, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install one (1) additional 9 kg foam fire extinguisher, one (1) additional 9 kg Co2 fire extinguisher and two (2) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb. To install Water pressure pump of at least 8 bar.\r\nc. To increase the water reserve tank capacity to a minimum of 30 m³.\r\nd. To install fire alarm system with control panel.\r\ne. To avail first aid kit and trained security staff from registered security company.\r\nf. To display emergency evacuation plan, emergency assembly point, and emergency hotline.\r\ng. To maintain CCTV cameras and increase their storage capacity in order to retain footage for at least three (3) months.\r\nh. To display entrance and exit using retro-reflective material.\r\ni. To install emergency, stop switch, automatic power backup system (generator), and lightning protection system.\r\nj. To avail toilet for person with disabilities.\r\nk. To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw within two weeks.', NULL, NULL, 57.50, 100.00, 57.50, NULL, NULL, NULL, NULL, '2026-08-10 13:10:23', '2026-08-26 12:33:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(67, NULL, 60, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-04', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'the station do not comply with fire safety and security system', '1. Remove the kitchen and bar at the station \r\n   DARE RWANDA and MAGGIES BAR AND GRILL must be removed from the station immediately.\r\n   \r\n2. Increase fire pump pressure to at least 8 bar and increase water tank capacity dedicated to firefighting.\r\n\r\n3. Repair the fire alarm system and ensure it is working properly.\r\n\r\n4. Test the lightning protection system every 6 months and record the test results.\r\n\r\n5. Provide additional fire extinguishers: \r\n   - 6kg ABC Dry Powder (2 units)\r\n   - 9kg CO₂ (1 unit)\r\n\r\n6. Provide an emergency evacuation plan, exit signs, and display emergency response phone numbers.\r\n\r\n7. Provide illuminated entrance and exit signs.\r\n\r\n8. Open emergency exits  they are currently closed.\r\n\r\n9. Mount CO₂ fire extinguishers that are currently placed on the floor.', NULL, NULL, 78.50, 100.00, 78.50, NULL, NULL, NULL, NULL, '2026-08-10 13:12:54', '2026-08-10 13:12:54', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(68, NULL, 61, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, NULL, '•  1. Firefighting System Repair & Upgrade: Fix the failed water pump and upgrade the water tank capacity to 30m3.\r\n•  2. Fire Alarm Installation: Set up a complete fire alarm system with smoke detectors, manual call points, and a main control panel.\r\n•  3. Extra Fire Extinguishers: Supply additional extinguishers, including one 25 kg DCP, two 9 kg CO2, and two foam units.\r\n•  4. Clear Safety Signage: Post visible markers for entrances, exits, emergency phone numbers, and the assembly point.\r\n•  5. CCTV Storage Expansion: Expand CCTV video storage capacity to retain footage for at least 3 months.\r\n•  6. Required Documents Submission: Email the occupation permit, calibration certificate, electrical installation certificate, and lightning test results to inspection@gasabo.gov.rw within 3 days', NULL, NULL, 65.50, 100.00, 65.50, NULL, NULL, NULL, NULL, '2026-08-10 13:16:08', '2026-08-10 13:16:08', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(69, NULL, 62, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install one (1) additional 9 kg foam fire extinguisher and one (1) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb. To increase the water pressure in the fire hydrant and hose reel by installing a water pressure pump rated at 8–15 bar.\r\nc. To increase the water reserve tank capacity to a minimum of 30 m³.\r\nd. To put two shovels in sand box.\r\ne. To maintain or replace fire alarm system with control panel.\r\nf. To display emergency evacuation plan.\r\ng. To establish an accessible CCTV control room at the petrol station and ensure that the system has sufficient storage capacity to retain surveillance footage for at least three (3) months.\r\nh. To avail trained security staff from a registered security company.\r\ni. To carry out maintenance of generator and ensure that it operates automatically.\r\nj. To conduct lightning protection system testing every six (6) months and maintain proper test records for verification during inspections.\r\nk. To display appropriate warning notices and pictograms on the canopy columns, vent pipes, and storage tanks, ensuring they are clearly visible from a distance of at least 7.5 m.\r\nl. To display entrance and exit signs using illuminated retro-reflective materials, ensuring they are clearly visible from a distance of at least 50 m.\r\nn. To provide appropriate personal protective equipment (PPE), including safety shoes, to all staff.\r\nn. To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw within two weeks.', NULL, NULL, 56.00, 100.00, 56.00, NULL, NULL, NULL, NULL, '2026-08-10 13:23:08', '2026-08-10 15:45:51', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70, NULL, 63, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, NULL, '1. To install water bucket fire fighting system (tank of 50 cubic meter, pumping & hose, hose reels, and fire hydrants)\r\n2. To provide additional fire extinguishers (2 pieces of 9kg DCP, 2 pieces of 9kg CO2, and 2 pieces 9kg foam)\r\n3. To install enough cameras with control room (storage capacity should be 3 months)\r\n4. To test earthing system regularly every 06 months and keep test result record\r\n5. To install fully functional fire alarm system (smoke detectors, call points, and control panel)\r\n6. To identify and mark assembly point with emergency phone number\r\n7. To provide retail license, calibration certificate, occupation permit via email\r\n8. To provide fire extinguishers in buildings on station plot', NULL, NULL, 40.00, 99.00, 40.40, NULL, NULL, NULL, NULL, '2026-08-10 13:23:32', '2026-08-20 12:48:52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(71, NULL, 64, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install one (1) additional 9 kg foam fire extinguisher, one (1) additional 9 kg DCP (Dry Chemical Powder) fire extinguisher and two (2) additional 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nb. To maintain water based firefighting system (fire hydrants and hose reel) to ensure they are fully operational.\r\nc. To increase the water reserve tank capacity to a minimum of 30 m³.\r\nd. To install Water pressure pump of at least 8 bar.\r\ne. To provide two shovels in sand box.\r\nf. To install fire alarm system with control panel. \r\ng. To increase the storage capacity of CCTV cameras in order to retain footage for at least three (3) months.\r\nh. To install an automatic backup generator.\r\ni. To conduct lightning protection system testing every six (6) months and maintain proper test records for verification during inspections.\r\nj. To send electrical compliance certificate, copy of EIA certificate, construction permit, occupation permit, Fuel tank calibration certificate, Retail license, valid insurance to city of Kigali email: info@kigali.gov.rw within two weeks.', NULL, NULL, 67.00, 100.00, 67.00, NULL, NULL, NULL, NULL, '2026-08-10 13:30:19', '2026-08-10 16:04:20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(72, NULL, 65, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-06', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To install a water-based firefighting system, including a fire hydrant, hose reel, a water pump with a minimum pressure of 8-15 bar, and a water storage tank with a capacity of at least 30 m³ for firefighting purposes.\r\nb. To install additional One (1) 9 kg CO₂ fire extinguisher, One (1) 9 kg foam fire extinguisher, and One (1) 25 kg DCP (Dry Chemical Powder) fire extinguisher.\r\nc. To provide dry fine with two shovels.\r\nd. To Install a fire alarm system with a control panel. \r\ne. To install digital CCTV cameras with a minimum storage capacity of 90 days.\r\nf. To develop and implement an emergency evacuation plan\r\ng. To install clearly visible entrance and exit signs made of illuminated retro-reflective material, ensuring they are easily readable from a minimum distance of 50 meters.\r\nh. To hire security staff from a registered security company.\r\ni. To install a lightning protection system and an emergency stop switch.\r\nj. To send copies of the following valid documents to CoK: Electrical installation compliance certificate, EIA (Environmental Impact Assessment) certificate, construction permit, Occupation permit, Tank Calibration Certificate, Dispenser test certificate, Retail License, and Valid Insurance Certificate. These documents may be submitted via email to: info@kigalicity.gov.rw', NULL, NULL, 59.00, 100.00, 59.00, NULL, NULL, NULL, NULL, '2026-08-10 14:32:05', '2026-08-11 04:50:45', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(73, NULL, 66, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To maintain all water-based firefighting equipment, including hose reels and fire hydrants. \r\nb. To Maintain the firefighting water pump at a pressure range of 8 to 15 bar.\r\nc. To increase the water tank storage capacity to at least 30 m³.\r\nd. To Provide additional One (1) 9 kg Foam Fire Extinguisher; One (1) 9 kg CO₂ Fire Extinguisher; and One (1) 25 kg DCP (Dry Chemical Powder) Fire Extinguisher.\r\ne. To Provide dry fine sand with two shovels.\r\nf. To maintain CCTV cameras in good working condition and ensure a minimum video storage capacity of 90 days.\r\ng. To test and maintain the lightning protection system at least once every six (6) months and keep valid test certificates available for inspection.\r\nh. To establish and implement a proper drainage and wastewater management system.\r\ni. to submit copies of the following valid documents to the City of Kigali: Electrical installation compliance certificate; Environmental Impact Assessment (EIA) Certificate; Fuel Tank Calibration Certificate; Dispenser Test Certificate; Retail License; and Valid Insurance Certificate.\r\nDocuments should be submitted via email to info@kigalicity.gov.rw within two weeks.', NULL, NULL, 51.00, 100.00, 51.00, NULL, NULL, NULL, NULL, '2026-08-10 14:55:48', '2026-08-11 06:27:20', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(74, NULL, 66, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 2, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To maintain all water-based firefighting equipment, including fire hose reels and fire hydrants, in good working condition. \r\nb. To maintain firefighting water pump.\r\nc. To increase the water storage tank capacity to at least 30 m³.\r\nd. Provide  additional one (1) 9 kg foam fire extinguisher and two (2) 25 kg Dry Chemical Powder (DCP) fire extinguishers.\r\ne. To provide  dry fine sand  with at least two shovels.\r\nf. To maintain the CCTV system in good working condition and increase its storage capacity to retain surveillance footage for a minimum of 90 days.\r\ng. To conduct periodic testing of the lightning protection system at least once every six (6) months and maintain valid test records for inspection.\r\nh. To establish and maintain an appropriate drainage and wastewater management system to prevent environmental pollution.\r\ni. To Send copies of the following valid documents to the City of Kigali via info@kigalicity.gov.rw: electrical installation compliance certificate; environmental impact assessment (EIA) Certificate; fuel tank calibration certificate; dispenser test certificate; retail license; and valid insurance within two weeks.', NULL, NULL, 52.50, 100.00, 52.50, NULL, NULL, NULL, NULL, '2026-08-10 15:07:00', '2026-08-26 08:30:37', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(75, NULL, 67, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-05', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To increase the water pressure in the hose reel and fire hydrant system by connecting them to a dedicated water pump (8-15 bar).\r\n b. To increase the water tank storage capacity to at least 30 m³.\r\nd. To provide sufficient dry fine sand with two shovels in the sand box.\r\ne. To maintain the fire alarm system, including the control panel and smoke detectors.\r\nf. To develop and implement an emergency evacuation plan and provide adequate first-aid kits.\r\ng. To increase the CCTV system storage capacity to maintain video recordings for a minimum of 90 days.\r\nh. To install One (1) additional 9 kg Foam Fire Extinguisher; and One (1) additional 9 kg CO₂ Fire Extinguisher.\r\ni. To conduct testing of the lightning protection system and make available valid inspection and test records.\r\nj. To send the following valid documents to the City of Kigali: Electrical Installation Compliance Certificate; Environmental Impact Assessment (EIA) Certificate; Construction Permit; Occupation Permit; Fuel Tank Calibration Certificate; Dispenser Test Certificate; Retail License; and Valid Insurance Certificate. The documents should be submitted via email to info@kigalicity.gov.rw within two weeks.', NULL, NULL, 51.50, 100.00, 51.50, NULL, NULL, NULL, NULL, '2026-08-11 07:27:09', '2026-08-11 07:27:09', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(76, NULL, 68, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-12', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, 'The premises have several safety and compliance gaps, including inadequate firefighting facilities, incomplete electrical documentation, insufficient firefighting tools, missing required licences and certificates, and inadequate accessibility facilities.', '1.Install a water-based firefighting system, including an automatic pump, a 30 m³ water tank, hydrants, and hose reels covering the entire compound.\r\n2.Service the electrical installation and obtain a valid Electrical Installation Compliance Certificate.\r\n3.Provide one shovel in each sand bucket.\r\n4.Provide valid documentation, including the fuel tank calibration certificate, retail licence, valid insurance certificate, installation certificate, and inspection 5.report/email from the relevant authority.\r\n6.Provide adequate fire extinguishers, including one 9 kg DCP extinguisher and one 25 kg DCP extinguisher.\r\n7.Install a functional toilet facility for persons with disabilities.', NULL, NULL, 68.00, 100.00, 68.00, NULL, NULL, NULL, NULL, '2026-08-12 06:39:11', '2026-08-12 12:45:14', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(77, NULL, 69, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-12', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, NULL, 'To do maintenance of fire alarm system to make it fully functional and cover all buildings.\r\nTo install water-based fire fighting system (water reservoir of 30 cubic meters, pump of 8 bars, hose reel and hydrant)\r\nTo provide extinguishers (2 pieces of 25kg DCP, 2 pieces of 9 Kg  DCP, 2 pieces of 9kg CO2, 2 pieces of 9kg foam)\r\nTo remove kitchen and bar from petrol station compound\r\nTo test firefighting system so as to check its effectiveness and keep test results (every six month)\r\nTo revise electrical installation or conduct audit and obtain electrical installation compliance certificate\r\nTo do maintenance of CCTV cameras and make them working, ensure that their storage capacity is 3 months\r\nTo make the back up generator automatic in case of power failure\r\nTo provide and mount Evacuation Plan, assembly point, emergency exit phone number, entrance and exit signs clearly readable from minimum distance of 50 meters\r\nTo provide Calibration Certificate, occupation permit and retail license via email\r\nTo provide toilet for people with disability', NULL, NULL, 62.50, 99.00, 63.13, NULL, NULL, NULL, NULL, '2026-08-12 06:52:00', '2026-08-12 13:45:54', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(78, '665/07.01.14/26', 70, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-12', 'new', NULL, 1, 'completed', 14, 'ITANGISHAKA Fidele', 2, NULL, 'Gushyiraho ibikoresho byo kuzimya umuriro bihagije\nGusana urumuri rw\'inzira y\'abatembera muri sitasiyo\nKubona icyemezo cy\'ubwishingizi kigezweho', NULL, NULL, 45.50, 100.00, 45.50, NULL, '2026-09-04 06:14:13', NULL, NULL, '2026-08-12 06:59:02', '2026-09-04 06:14:13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(79, NULL, 71, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-12', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'Partial complying', '1. *Increase water pump capacity*  \r\n   Achieve a minimum pressure of up to 8 bar.\r\n\r\n2. *Upgrade CCTV camera storage*  \r\n   Increase storage capacity to retain footage for up to 3 months (90 days).\r\n\r\n3. *Display assembly point signage*  \r\n   Install a sand box and provide a white sign.\r\n\r\n4. *Provide emergency signage*  \r\n   Install illuminated entrance and exit signs.\r\n\r\n5. *Increase firefighting water storage*  \r\n   Provide a water storage tank with a capacity of up to 30 m³.\r\n\r\n6. *Provide additional fire extinguishers*  \r\n   Provide an additional 25kg DCP fire extinguisher.\r\n\r\n7. *Display warning signs*  \r\n   Display all required warning signs at the storage tank.\r\n\r\n8. *Avail required documents*  \r\n   Submit a valid Insurance Certificate and Retail License.\r\n\r\n\r\n10. *Provide changing facilities*  \r\n    Provide separate changing rooms for male and female staff.', NULL, NULL, 78.50, 100.00, 78.50, NULL, NULL, NULL, NULL, '2026-08-12 07:04:32', '2026-08-12 08:58:26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(80, NULL, 72, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-12', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To Send the following valid documents to the City of Kigali via email info@kigalicity.gov.rw: Electrical installation compliance certificate; Construction Permit; Occupation Permit; Fuel Tank Calibration Certificate; dispenser test certificate; Environmental Impact Assessment (EIA) Certificate; Retail License; and valid insurance within two weeks.\r\nb. To maintain fire alarm system in good working condition, including the control panel and all associated devices.\r\nc. To install emergency stop switch at an accessible location.\r\nd. To maintain the water-based firefighting system and increase the water storage tank capacity to at least 30 m³. \r\ne. To ensure that the firefighting water pump provides adequate pressure of 8-15 bar to the hose reels and fire hydrant system.\r\nf. To install an automatic standby generator to ensure continuous power supply during outages and reliable operation at all times.\r\ng. To conduct periodic testing of the lightning protection system (every six months) and keep valid test records available for inspection.\r\nh. To install clearly visible public toilet signage and other required safety signs including assembly point signs.\r\ni. To Provide additional one (1) 9 kg Foam Fire Extinguisher; and one (1) 25 kg Dry Chemical Powder (DCP) Fire Extinguisher.', NULL, NULL, 42.50, 100.00, 42.50, NULL, NULL, NULL, NULL, '2026-08-12 07:12:41', '2026-08-12 10:16:55', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(81, NULL, 73, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-12', 'new', NULL, 1, 'completed', 8, 'NIYINGENERA Thierry', 1, 'Not complying', 'To install water based firefighting system (water tank 30m³, water pump of 8bars, hose reels and fire hydrants)\r\n​To provide additional fire extinguishers (2 pieces of 25kg DCP, 2 pieces of 5kg CO2 and 2 pieces of 9kg foam)\r\n​To do maintenance of fire alarm system\r\n​To provide entrance and exit signs (illuminated) visible in a minimum distance of 50 meters\r\n​To identify and mark assembly point, evacuation plans\r\n​To provide facilities for people with disabilities (toilets, 1 for males and 1 for females) at least one toilet\r\n​To avail and install fuel price board (poster)', NULL, NULL, 57.50, 99.00, 58.08, NULL, NULL, NULL, NULL, '2026-08-12 07:40:39', '2026-08-12 13:36:57', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(82, NULL, 74, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-12', 'new', NULL, 1, 'completed', 19, 'NSENGIMANA Private', 1, 'The premises have several safety gaps, including the absence of a fire alarm system, insufficient fire extinguishers, inadequate CCTV coverage, lack of a clearly designated assembly point, and expired fire extinguishers.', 'Install a functional fire alarm system with a suitable control panel.\r\nProvide additional 9 kg fire extinguishers as required.\r\nInstall a CCTV system covering the entire compound, with at least 3 months of recording storage.\r\nProvide and clearly mark an assembly point in a designated area.\r\nService or replace all expired fire extinguishers.', NULL, NULL, 63.50, 100.00, 63.50, NULL, NULL, NULL, NULL, '2026-08-12 07:43:40', '2026-08-13 07:41:24', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(84, NULL, 76, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-12', 'new', NULL, 1, 'completed', 9, 'UWIKUNDA Idesbald', 3, NULL, 'a. To immediately stop kitchen operations within the petrol station premises.\r\nb. To maintain the water-based firefighting system and increase the water storage tank capacity to at least 30 m³.\r\nc. To provide additional one (1) 9 kg Foam Fire Extinguisher; and one (1) 25 kg Dry Chemical Powder (DCP) Fire Extinguisher.\r\nd. To Conduct periodic testing of the lightning protection system (every 6months) and keep valid test records available for inspection.\r\ne. To Send the following documents by email to info@kigalicity.gov.rw: construction permit, occupation permit, EIA (Environmental impact assessment) certificate, valid insurance, Electrical installation compliance certificate, Retail license, Fuel tank calibration certificate, and dispenser test certificate.', NULL, NULL, 51.00, 100.00, 51.00, NULL, NULL, NULL, NULL, '2026-08-12 08:23:57', '2026-08-12 11:09:32', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(85, NULL, 77, 2, 'petrol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-12', 'new', NULL, 1, 'completed', 7, 'SENZIRA Eugene', 2, 'Partial complying', '1. *Install a fire pump*  \r\n   Provide a fire pump with a minimum pressure of 8 bar.\r\n\r\n2. *Install a water storage tank for firefighting*  \r\n   Provide a dedicated water tank with a minimum capacity of 30 m³.\r\n\r\n3. *Remove waste materials*  \r\n   Clear all waste materials stored in the electrical cabinet/power house.\r\n\r\n4. *Upgrade CCTV system*  \r\n   Install CCTV cameras with storage capacity for 3 months.  \r\n   Ensure the control room is accessible to the competent authority.\r\n\r\n5. *Display emergency information*  \r\n   Display the emergency evacuation plan, exit signs, and emergency response phone numbers.\r\n\r\n6. *Test lightning protection system*  \r\n   Conduct lightning protection testing every six months and submit the test results.\r\n\r\n7. *Improve hygiene*  \r\n   Improve hygiene around the water tank area.\r\n\r\n8. *Provide a first aid kit*  \r\n   Provide a first aid kit stocked with all required elements.\r\n\r\n9. *Submit required documents*  \r\n   Avail the following documents via email: info@city.kigalicity.gov.rw  \r\n   a) Valid Insurance  \r\n   b) Retail License\r\n\r\n10. *Provide accessibility ramp*  \r\n    Provide a ramp for persons with disabilities.\r\n\r\n11. *Provide changing rooms*  \r\n    Provide separate changing rooms for both male and female staff.', NULL, NULL, 80.00, 100.00, 80.00, NULL, NULL, NULL, NULL, '2026-08-12 08:57:09', '2026-08-12 08:57:14', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
